insert into currency_bias (currency, current_level, current_summary, current_started_at) values ('USD', 'neutral', 'A PESAR DE LOS DATOS DE INFLACION DE LA SEMANA ANTERIOR,LOS CUALES MODIFICARON LA PREVISION DE UNA SUBIDA DE TIPOS DE INTERES, LAS SOLICITUDES POR DESEMPLEO SIGUEN MOSTRANDO UN MERCADO LABORAL SOLIDO, LOS PMIS FLASH MOSTRARON UNA ACTIVIDAD ECONOMICA MUY POSITIVA  ESPECIALMENTE EN EL SECTOR DE SERVICIOS, ASI MISMO EL REPUNTE DEL PRECIO DEL PETROLEO LE DA CIERTO SOPORTE AL DOLAR AL SER UN PAIS EXPORTADOR DEL MISMO, A SU VEZ MODIFICA LA PREVISIONES DE TIPOS YA QUE CRECEN LOS EXPECTATIVAS DE UNA INFLACION MAS ALTA ', '2026-07-27') on conflict (currency) do update set current_level = excluded.current_level, current_summary = excluded.current_summary, current_started_at = excluded.current_started_at;
insert into currency_bias (currency, current_level, current_summary, current_started_at) values ('EUR', 'neutral_alcista', 'A PESAR DE LA SUBIDA DEL PRECIO DEL PETROLEO Y LA ZONA EUROPEA SER UN PAIS DEPENDIENTE DE LA ENERGIA, EL IMPACTO NO HA SIDO TAN NEGATIVO YA QUE DICHO AUMENTO DE LA ENERGIA AUMENTA A SU VEZ LAS PREVISIONES DE TIPOS DE INTERES, A NIVEL MACROECONOMICO INDICADORES DE CONFIANZA COMO EL ZEW MOSTRARON MEJORA EN LA CONFIANZA DE LOS INVERSORES, LA DESICION DE TIPOS DEL BCE LIGERAMENTE ALCISTA CON LA PRESIDENTA LAGARDE INSISTIENDO EN QUE LOS EFECTOS DE SEGUNDA RONDA AUN NO SE HAN MATERIALIZADO, POR EL ULTIMO LOS PMIS MOSTRARON UNA RECUPERACION GLOBAL DE LA ECONOMIA LO CUAL A SU VEZ NOS DICE QUE SE EL BCE PUEDE SUBIR TIPOS SI LAS PRESIONES INFLACIONARIAS AUMENTAN SIN TENER UN EFECTO NEGATIVO A CORTO PLAZO ', '2026-07-27') on conflict (currency) do update set current_level = excluded.current_level, current_summary = excluded.current_summary, current_started_at = excluded.current_started_at;
insert into currency_bias (currency, current_level, current_summary, current_started_at) values ('CAD', 'dovish', 'SEMANA CONTUNDENTE PARA EL CAD, LOS DATOS DE INFLACION SE MODERARON CONSIDERABLEMENTE, Y EN CONSONANCIA CON EL BOC, LA INFLACION QUE VIGILA DE CERCA EL BOC (MEDIA RECORTADA-MEDIA PONDERADA), SE SITUARON POR DEBAJO DEL 2%, EN SEGUNDA INSTANCIA LA ADMINISTRACION TRUMP IMPUSO ARANCELES DEL 50% A CANADA QUE AFECTARIAN A UNOS 20.000 MILLONES DE DOLARES, LO CUAL AFIRMA COMO HA DICHO EL BOC QUE PUEDEN ESTAR DISPUESTOS A BAJAR TIPOS DE INTERES SI LAS TENSIONES COMERCIALES AUMENTAN SIGNIFICATIVAMENTE ', '2026-07-27') on conflict (currency) do update set current_level = excluded.current_level, current_summary = excluded.current_summary, current_started_at = excluded.current_started_at;
insert into currency_bias (currency, current_level, current_summary, current_started_at) values ('GBP', 'neutral', ' SEMANA PARA LA LIBRA LLENA DE MUCHA INFORMACION, LOS DATOS DE EMPLEO MOSTRARON UN CRECIMIENTO DE DE 147MIL NOMINAS, LA TASA DE DESEMPLEO DESCENDIO AL 4.9% MIENTRAS LOS SALARIOS INCLUYENDO BONUS SE RELAJARON AL 4.3%, LA INFLACION GENERAL SE MODERO AUNQUE YA DESCONTADO EN PARTE A LA CAIDA DE LOS PRECIOS DE LA ENERGIA  DEL MES ANTERIOR, MIENTRAS LA INFLACION SUBYACENTE SE MANTUVO SIN CAMBIOS, YA PARA TERMINAR LA SEMANA LOS PMIS MEJOR DE LO PREVISTO Y LAS VENTAS MINORISTAS MOSTRARON UNA GRAN MEJORA DE LA DEMANDA INTERNA ', '2026-07-27') on conflict (currency) do update set current_level = excluded.current_level, current_summary = excluded.current_summary, current_started_at = excluded.current_started_at;
insert into currency_bias (currency, current_level, current_summary, current_started_at) values ('AUD', 'neutral_alcista', 'FUERTE RECUPERACION DEL EMPLEO EN UNA DIVISA QUE YA ESTABA ENFOCADA EN LOS EFECTOS DE 3 SUBIDAS CONSECUTIVAS ESTE ANO, EL MERCADO AUN SIGUE POSICIONADO A UNA PAUSA O UNA SUBIDA DE 25PTS BASICOS ESTE ANO, LOS DATOS DE INFLACION DE ESTA SEMANA PODRIAN MODIFICAR DRASTICAMENTE ESTA LECTURA, LOS PMIS MOSTRARON UNA FUERTE MEJORA DE LA ACTIVIDAD ECONOMICA ', '2026-07-27') on conflict (currency) do update set current_level = excluded.current_level, current_summary = excluded.current_summary, current_started_at = excluded.current_started_at;
