insert into currency_bias (currency, current_level, current_summary, current_started_at) values ('JPY', 'neutral_alcista', 'SIN MUCHOS CAMBIOS RELEVANTES EN LA SEMANA EL SESGO SE MANTIENE Y SE REAFIRMA, ESPECIALMENTE LOS DATOS DE CRECIMIENTO PRELIMINARES COMO LOS PMIS, MUESTRAS UNA MEJORA EN LA ACTIVIDAD ECONOMICA, LOS DATOS DE INFLACION AUNQUE PARCIALMENTE IGUAL QUE LAS PREVISIONES MOSTRARON CIERTA RECUPERACION DE LA INFLACION SUBYACENTE (AUN POR DEBAJO DEL 2%) PERO REAFIRMA LA INTENCION DEL BOJ DE UNA SUBIDA CADA MENOS DE 6 MESES. ', '2026-07-27') on conflict (currency) do update set current_level = excluded.current_level, current_summary = excluded.current_summary, current_started_at = excluded.current_started_at;
