insert into currency_bias_history (id, currency, level, summary, reasons, started_at) values ('SES-260720113142-317', 'EUR', 'neutral_bajista', 'SABIENDO QUE EN EUROPA ES MOTOR INDUSTRIAL, LOS DATOS DE PRODUCCION AHORA EN CONTRACCION CONFIRMAN UNA DESACELERACION EN EL CRECIMIENTO, LOS DATOS DE INFLACION (FINALES) NO SORPRENDIERON SALIERON EN BASE AL CONSENSO, MOTIVO DE LA CAIDA DE LOS PRECIOS DE LA ENERGIA EL MES PASADO...... A ESPERA DE MAS CONTEXTO CON LA DESICION DE TIPOS ESTA SEMANA YA QUE EL PETROLEO VUELVE A REPUNTAR DESPUES DE QUE SE ATENUARAN LAS TENSIONES GEOPOLITICAS', '[{"id": "SES-260720113142-317-R0", "label": "PRODUCCION INDUSTRIAL, INFLACION(DESCONTADO)", "color": "neutral_bajista", "headlineId": null}]'::jsonb, '2026-07-20') on conflict (id) do nothing;
